// ==== Filtros con botones y animaciones ====================================
//
// Este script va en el objeto "mesh_0" (la mascara facial). Los tres Plane del
// editor (filtro_crema, filtro_balsamo, filtro_perfume) son solo "bandejas" de
// textura: al arrancar se ocultan y su imagen se pinta sobre la cara, con
// animacion, cuando se pulsa un boton de la web.
//
//   this -> mesh_0
//   player.setFilter("crema")    -> aplica una parte mas de la crema
//   player.setFilter("balsamo")  -> el labial se "coloca" sobre los labios
//   player.setFilter("perfume")  -> aparecen los destellos
//   player.setFilter(null)       -> sin nada
//
// Cada filtro tambien tiene un sonido que se dispara con un gesto de la cara
// (parpadeo, sonrisa, cejas). Solo suena el del filtro que esta activo.
// Los gestos se miden aqui mismo (ver GESTOS) para poder ajustar la sensibilidad.
//
// Las tres texturas deben tener el mismo tamaño y la misma distribucion UV que
// la textura de la cara (1024 x 1024 en tu escena).

// ---- Configuracion --------------------------------------------------------

// id       nombre que usan los botones.
// plano    nombre del Plane que guarda la textura.
// veces    cuantas veces se pinta la capa (sube el numero si se ve muy tenue).
// modo     'partes'    cada clic en el boton coloca una parte mas (crema).
//          'aplicar'   la capa se "pasa" de lado a lado, como un labial.
//          'destellos' cada estrella aparece con un pop y luego titila.
// duracion milisegundos de la animacion (en 'destellos', de cada estrella).
const FILTROS = [
	{ id: 'crema',   plano: 'filtro_crema',   veces: 1, modo: 'partes',    duracion: 550 },
	{ id: 'balsamo', plano: 'filtro_balsamo', veces: 4, modo: 'aplicar',   duracion: 900 },
	{ id: 'perfume', plano: 'filtro_perfume', veces: 1, modo: 'destellos', duracion: 450 }
];

// ---- Sonidos --------------------------------------------------------------
// filtro    el sonido solo suena cuando este filtro esta activo.
// url       tu archivo de sonido (cambia cada url por el sonido que quieras).
// inicio    gesto que lo hace sonar:
//             'blink'      parpadeo          (termina con 'blinkEnd')
//             'smileStart' sonrisa           (termina con 'smileEnd')
//             'browRaise'  subir las cejas   (termina con 'browLower')
// fin       gesto que lo detiene, o null para dejar que termine solo.
// volumen   de 0 a 1.
const SONIDOS = [
	{ filtro: 'crema',   nombre: 'sonido_crema',   url: 'https://filtrokora.vercel.app/assets/mediapipe/slime.mp3', inicio: 'blink',      fin: null,        volumen: 1 },
	{ filtro: 'balsamo', nombre: 'sonido_labial',  url: 'https://filtrokora.vercel.app/assets/mediapipe/beso.mp3', inicio: 'smileStart', fin: 'smileEnd',  volumen: 1 },
	{ filtro: 'perfume', nombre: 'sonido_perfume', url: 'https://filtrokora.vercel.app/assets/mediapipe/shine.mp3', inicio: 'browRaise',  fin: 'browLower', volumen: 1 }
];

// ---- Gestos: sensibilidad -------------------------------------------------
// entrar  valor (0 a 1) que hay que superar para que cuente el gesto.
// salir   valor por debajo del cual el gesto se considera terminado.
// Si un gesto cuesta detectarlo, BAJA "entrar"; si se activa solo, SUBELO.
const GESTOS = {
	blink:      { fin: 'blinkEnd',  entrar: 0.30, salir: 0.15, valor: () => (face ? face.blink : 0) },
	smileStart: { fin: 'smileEnd',  entrar: 0.35, salir: 0.20, valor: () => (face ? face.smile : 0) },
	browRaise:  { fin: 'browLower', entrar: 0.35, salir: 0.20, valor: () => (face ? face.browRaise : 0) }
};

// true = muestra arriba a la izquierda los valores de la cara y el estado de los
// sonidos (util para probar). Ponlo en false cuando todo funcione.
const DEPURAR = true;

// Crema: 0 = un clic aplica todas las manchas, una tras otra.
//        1 (o mas) = cada clic agrega esa cantidad de manchas.
const CREMA_PARTES_POR_CLIC = 0;
const CREMA_RETRASO = 350;     // ms entre una mancha y la siguiente

const FILTRO_INICIAL = null;        // null = al escanear no hay ningun filtro
const PINTAR_TEXTURA_BASE = false;  // false = sin la estrella, corazon ni pecas originales
const REINICIAR_CREMA = true;       // (si CREMA_PARTES_POR_CLIC > 0) al completar, otro clic empieza de nuevo
const FPS_ANIMACION = 30;           // limite de actualizaciones de la textura por segundo

// ---- Estado ---------------------------------------------------------------

const mascara = this;
const capas = {};              // id -> textura del plano
let base = null;               // textura original de la cara
let lienzo = null;
let ctx = null;
let textura = null;            // textura combinada que usa la mascara
let listo = false;
let sucio = true;
let animando = false;
let ultimoDibujo = 0;
let actual = FILTRO_INICIAL;
let panel = null;
let ultimoPanel = 0;
let ultimoMensaje = '';
let audioDesbloqueado = false;

// ---- Utilidades -----------------------------------------------------------

function limitar(v, min, max) {
	return Math.min(max, Math.max(min, v));
}

function easeOutBack(t) {
	const c1 = 1.70158;
	const c3 = c1 + 1;
	return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
}

function easeInOut(t) {
	return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}

// Las imagenes del JSON se decodifican un instante despues de cargar la escena.
function imagenLista(tex) {
	const im = tex && tex.image;
	if (!im) return false;
	if (im.complete === false) return false;
	return (im.naturalWidth || im.width || 0) > 0;
}

function buscarPlanos() {
	// 1) Por nombre.
	const porNombre = FILTROS.map((f) => scene.getObjectByName(f.plano));
	if (porNombre.every(Boolean)) return porNombre;

	// 2) Si no se renombraron: los Plane ordenados del mas cercano al mas lejano.
	const planes = [];
	scene.traverse((o) => {
		if (o.isMesh && o !== mascara && /^Plane/i.test(o.name)) planes.push(o);
	});
	planes.sort((a, b) => b.position.z - a.position.z);
	return FILTROS.map((f, i) => planes[i] || null);
}

function ocultarPlanos() {
	for (const p of buscarPlanos()) {
		if (p) p.visible = false;
	}
}

// ---- Deteccion de partes (cada estrella, cada mancha de crema) ------------

// Busca las "islas" de pixeles visibles de una capa y devuelve su rectangulo.
// Trabaja en una malla reducida (escala) para ser rapido; "dilatar" une los
// brillos y rayos que pertenecen a la misma figura.
function detectarPartes(alpha, w, h, umbral, escala, dilatar) {
	const gw = Math.ceil(w / escala);
	const gh = Math.ceil(h / escala);
	let malla = new Uint8Array(gw * gh);
	const cuenta = new Uint16Array(gw * gh);

	for (let y = 0; y < h; y++) {
		const fila = Math.floor(y / escala) * gw;
		for (let x = 0; x < w; x++) {
			if (alpha[y * w + x] > umbral) {
				const i = fila + Math.floor(x / escala);
				malla[i] = 1;
				if (cuenta[i] < 65535) cuenta[i]++;
			}
		}
	}

	for (let k = 0; k < dilatar; k++) {
		const nueva = malla.slice();
		for (let y = 0; y < gh; y++) {
			for (let x = 0; x < gw; x++) {
				if (!malla[y * gw + x]) continue;
				for (let dy = -1; dy <= 1; dy++) {
					for (let dx = -1; dx <= 1; dx++) {
						const nx = x + dx, ny = y + dy;
						if (nx >= 0 && ny >= 0 && nx < gw && ny < gh) nueva[ny * gw + nx] = 1;
					}
				}
			}
		}
		malla = nueva;
	}

	const visto = new Uint8Array(gw * gh);
	const partes = [];
	const pila = [];
	for (let inicio = 0; inicio < malla.length; inicio++) {
		if (!malla[inicio] || visto[inicio]) continue;
		let minX = gw, minY = gh, maxX = 0, maxY = 0, pixeles = 0;
		pila.push(inicio);
		visto[inicio] = 1;
		while (pila.length) {
			const i = pila.pop();
			const x = i % gw, y = (i - x) / gw;
			pixeles += cuenta[i];
			if (x < minX) minX = x;
			if (x > maxX) maxX = x;
			if (y < minY) minY = y;
			if (y > maxY) maxY = y;
			for (let dy = -1; dy <= 1; dy++) {
				for (let dx = -1; dx <= 1; dx++) {
					const nx = x + dx, ny = y + dy;
					if (nx < 0 || ny < 0 || nx >= gw || ny >= gh) continue;
					const j = ny * gw + nx;
					if (malla[j] && !visto[j]) { visto[j] = 1; pila.push(j); }
				}
			}
		}
		if (pixeles < 3) continue;   // motas sueltas
		const x0 = minX * escala, y0 = minY * escala;
		partes.push({
			x: x0,
			y: y0,
			w: Math.min(w, (maxX + 1) * escala) - x0,
			h: Math.min(h, (maxY + 1) * escala) - y0
		});
	}
	partes.sort((a, b) => a.x - b.x);
	return partes;
}

function leerAlpha(img, w, h) {
	const c = document.createElement('canvas');
	c.width = w;
	c.height = h;
	const x = c.getContext('2d', { willReadFrequently: true });
	x.drawImage(img, 0, 0, w, h);
	const d = x.getImageData(0, 0, w, h).data;
	const a = new Uint8Array(w * h);
	for (let i = 0; i < a.length; i++) a[i] = d[i * 4 + 3];
	return a;
}

function unir(partes) {
	let x0 = Infinity, y0 = Infinity, x1 = 0, y1 = 0;
	for (const p of partes) {
		x0 = Math.min(x0, p.x);
		y0 = Math.min(y0, p.y);
		x1 = Math.max(x1, p.x + p.w);
		y1 = Math.max(y1, p.y + p.h);
	}
	return { x: x0, y: y0, w: x1 - x0, h: y1 - y0 };
}

function analizarFiltro(f, tex, w, h) {
	let partes;
	try {
		const alpha = leerAlpha(tex.image, w, h);
		if (f.modo === 'aplicar') partes = detectarPartes(alpha, w, h, 2, 4, 0);
		else partes = detectarPartes(alpha, w, h, 8, 4, 1);
	} catch (e) {
		// Imagen de otro dominio: no se puede leer, se usa la capa completa.
		console.warn('Filtros: no se pudo analizar "' + f.id + '"', e);
		partes = [];
	}
	if (!partes.length) partes = [{ x: 0, y: 0, w: w, h: h }];
	f.partes = partes;
	f.caja = unir(partes);
	if (f.modo === 'aplicar') {
		f.temporal = document.createElement('canvas');
		f.temporal.width = Math.ceil(f.caja.w);
		f.temporal.height = Math.ceil(f.caja.h);
	}
}

// ---- Inicio ---------------------------------------------------------------

function iniciar() {
	if (listo) return true;

	const mat = mascara.material;
	if (!mat || !imagenLista(mat.map)) return false;

	const planos = buscarPlanos();
	const nuevas = {};
	for (let i = 0; i < FILTROS.length; i++) {
		const plano = planos[i];
		if (!plano) {
			console.warn('Filtros: no se encontro el plano de "' + FILTROS[i].id + '"');
			continue;
		}
		const tex = plano.material && plano.material.map;
		if (!imagenLista(tex)) return false;   // todavia cargando: reintenta en update
		nuevas[FILTROS[i].id] = tex;
	}
	Object.assign(capas, nuevas);

	base = mat.map;
	const w = base.image.naturalWidth || base.image.width;
	const h = base.image.naturalHeight || base.image.height;

	for (const f of FILTROS) {
		if (capas[f.id]) analizarFiltro(f, capas[f.id], w, h);
	}

	lienzo = document.createElement('canvas');
	lienzo.width = w;
	lienzo.height = h;
	ctx = lienzo.getContext('2d');

	// Misma orientacion y color que la textura original de la cara.
	textura = new THREE.CanvasTexture(lienzo);
	textura.flipY = base.flipY;
	textura.colorSpace = base.colorSpace;
	textura.wrapS = base.wrapS;
	textura.wrapT = base.wrapT;
	textura.anisotropy = base.anisotropy;

	mat.map = textura;
	mat.needsUpdate = true;

	listo = true;

	const f = FILTROS.find((x) => x.id === actual);
	if (f) iniciarAnimacion(f, performance.now());
	componer(performance.now());
	return true;
}

// ---- Animaciones ----------------------------------------------------------

function iniciarAnimacion(f, ahora) {
	if (!f.partes) return;
	f.inicio = ahora;

	if (f.modo === 'partes') {
		// Las manchas se colocan una tras otra.
		const total = f.partes.length;
		f.n = CREMA_PARTES_POR_CLIC === 0 ? total : Math.min(CREMA_PARTES_POR_CLIC, total);
		f.inicios = [];
		for (let i = 0; i < f.n; i++) f.inicios.push(ahora + i * CREMA_RETRASO);
	}

	if (f.modo === 'destellos') {
		// Las estrellas aparecen en orden aleatorio y cada una titila a su ritmo.
		const orden = f.partes.map((_, i) => i).sort(() => Math.random() - 0.5);
		f.estrellas = f.partes.map((p, i) => ({
			retraso: orden.indexOf(i) * 60 + Math.random() * 40,
			fase: Math.random() * Math.PI * 2,
			vel: 2.2 + Math.random() * 2.2
		}));
	}
}

function siguienteParte(f, ahora) {
	// Un clic aplica todo: otro clic vuelve a colocar la crema desde cero.
	if (CREMA_PARTES_POR_CLIC === 0) { iniciarAnimacion(f, ahora); return; }

	const total = f.partes.length;
	if (f.n >= total) {
		if (!REINICIAR_CREMA) return;
		iniciarAnimacion(f, ahora);
		return;
	}
	const hasta = Math.min(total, f.n + CREMA_PARTES_POR_CLIC);
	for (let i = f.n; i < hasta; i++) f.inicios[i] = ahora + (i - f.n) * CREMA_RETRASO;
	f.n = hasta;
}

function dibujarCapa(f, tex) {
	const veces = f.veces || 1;

	if (f.modo === 'partes') {
		for (let i = 0; i < f.n; i++) {
			const p = f.partes[i];
			const t = limitar((ahora - f.inicios[i]) / f.duracion, 0, 1);
			if (t < 1) animando = true;
			if (t <= 0) continue;                      // todavia no le toca
			// Crece desde el centro y se "asienta" con un pequeño rebote.
			const escala = 0.35 + 0.65 * easeOutBack(t);
			const dw = p.w * escala, dh = p.h * escala;
			const cx = p.x + p.w / 2, cy = p.y + p.h / 2;
			ctx.globalAlpha = Math.min(1, t * 3);
			for (let k = 0; k < veces; k++) {
				ctx.drawImage(tex.image, p.x, p.y, p.w, p.h, cx - dw / 2, cy - dh / 2, dw, dh);
			}
		}
		ctx.globalAlpha = 1;
		return;
	}

	if (f.modo === 'aplicar') {
		const b = f.caja;
		const t = limitar((ahora - f.inicio) / f.duracion, 0, 1);
		if (t < 1) animando = true;
		const suave = b.w * 0.25;                          // borde difuso del trazo
		const frente = -suave + easeInOut(t) * (b.w + 2 * suave);

		const tc = f.temporal.getContext('2d');
		tc.globalCompositeOperation = 'source-over';
		tc.clearRect(0, 0, f.temporal.width, f.temporal.height);
		for (let k = 0; k < veces; k++) {
			tc.drawImage(tex.image, b.x, b.y, b.w, b.h, 0, 0, b.w, b.h);
		}
		const grad = tc.createLinearGradient(frente - suave, 0, frente, 0);
		grad.addColorStop(0, 'rgba(0,0,0,1)');
		grad.addColorStop(1, 'rgba(0,0,0,0)');
		tc.globalCompositeOperation = 'destination-in';
		tc.fillStyle = grad;
		tc.fillRect(0, 0, f.temporal.width, f.temporal.height);
		tc.globalCompositeOperation = 'source-over';

		ctx.drawImage(f.temporal, b.x, b.y);
		return;
	}

	if (f.modo === 'destellos') {
		animando = true;                                   // los destellos no se detienen
		const seg = (ahora - f.inicio) / 1000;
		for (let i = 0; i < f.partes.length; i++) {
			const p = f.partes[i];
			const e = f.estrellas[i];
			const t = limitar((ahora - f.inicio - e.retraso) / f.duracion, 0, 1);
			if (t <= 0) continue;
			const brillo = 0.5 + 0.5 * Math.sin(seg * e.vel + e.fase);   // 0..1
			const escala = easeOutBack(t) * (0.8 + 0.3 * brillo);
			const dw = p.w * escala, dh = p.h * escala;
			const cx = p.x + p.w / 2, cy = p.y + p.h / 2;
			ctx.globalAlpha = Math.min(1, t * 2) * (0.45 + 0.55 * brillo);
			for (let k = 0; k < veces; k++) {
				ctx.drawImage(tex.image, p.x, p.y, p.w, p.h, cx - dw / 2, cy - dh / 2, dw, dh);
			}
		}
		ctx.globalAlpha = 1;
	}
}

let ahora = 0;   // instante del dibujo actual (lo usa dibujarCapa)

function componer(t) {
	ahora = t;
	animando = false;
	ctx.globalAlpha = 1;
	ctx.clearRect(0, 0, lienzo.width, lienzo.height);

	if (PINTAR_TEXTURA_BASE) ctx.drawImage(base.image, 0, 0, lienzo.width, lienzo.height);

	const f = FILTROS.find((x) => x.id === actual);
	if (f && capas[f.id] && f.partes) dibujarCapa(f, capas[f.id]);

	textura.needsUpdate = true;
	sucio = false;
	ultimoDibujo = t;
}

// ---- Sonidos --------------------------------------------------------------

function mensaje(txt) {
	ultimoMensaje = txt;
	console.log('[filtros] ' + txt);
}

// player.loadAudio devuelve un reproductor HTML (no tiene isPlaying): se mira
// el elemento <audio> de adentro.
function estaSonando(a) {
	if (typeof a.isPlaying === 'boolean') return a.isPlaying;
	const el = a.audio;
	return !!el && typeof el.paused === 'boolean' && !el.paused;
}

// Carga cada sonido una sola vez, igual que con player.loadAudio de siempre.
for (const so of SONIDOS) {
	if (!player || typeof player.loadAudio !== 'function') break;   // vista previa del editor
	so.audio = player.loadAudio(so.nombre, so.url, (audio) => {
		audio.setLoop(false);
		audio.setVolume(so.volumen);
	});
	const el = so.audio && so.audio.audio;
	if (el && el.addEventListener) {
		el.preload = 'auto';
		el.addEventListener('error', () => mensaje('ERROR: no carga ' + so.nombre + ' -> ' + so.url));
	}
}

// Safari/iOS solo deja sonar un audio si antes se toco la pantalla: con el
// primer toque se "desbloquean" todos (en silencio).
function desbloquearAudios() {
	if (audioDesbloqueado) return;
	audioDesbloqueado = true;
	for (const so of SONIDOS) {
		const el = so.audio && so.audio.audio;
		if (!el || typeof el.play !== 'function') continue;
		el.muted = true;
		const fin = () => { el.pause(); el.currentTime = 0; el.muted = false; };
		let r;
		try { r = el.play(); } catch (e) { el.muted = false; continue; }
		if (r && r.then) r.then(fin).catch(() => { el.muted = false; });
		else fin();
	}
}
if (typeof document !== 'undefined') {
	document.addEventListener('pointerdown', desbloquearAudios, { once: true });
}

function reproducir(so) {
	const a = so.audio;
	try {
		let r;
		if (a.audio && typeof a.audio.play === 'function') {
			a.audio.currentTime = 0;
			r = a.audio.play();
		} else {
			r = a.play();
		}
		if (r && r.catch) r.catch((e) => mensaje('no se pudo reproducir ' + so.nombre + ': ' + e.name));
		mensaje('suena ' + so.nombre);
	} catch (e) {
		mensaje('no se pudo reproducir ' + so.nombre + ': ' + e.message);
	}
}

function sonar(gesto) {
	const so = SONIDOS.find((x) => x.filtro === actual && x.inicio === gesto);
	if (!so || !so.audio || estaSonando(so.audio)) return;
	reproducir(so);
}

function callar(gesto) {
	const so = SONIDOS.find((x) => x.filtro === actual && x.fin === gesto);
	if (!so || !so.audio || !estaSonando(so.audio)) return;
	try { so.audio.stop(); } catch (e) { /* nada */ }
}

function callarTodos() {
	for (const so of SONIDOS) {
		try { if (so.audio && estaSonando(so.audio)) so.audio.stop(); } catch (e) { /* nada */ }
	}
}

// Mide los gestos de la cara cada cuadro y dispara los sonidos.
function procesarGestos() {
	if (!face) return;
	for (const nombre in GESTOS) {
		const g = GESTOS[nombre];
		const v = g.valor();
		if (!g.activo && v > g.entrar) {
			g.activo = true;
			mensaje('gesto ' + nombre + ' (' + v.toFixed(2) + ') con el filtro "' + (actual || 'ninguno') + '"');
			sonar(nombre);
		} else if (g.activo && v < g.salir) {
			g.activo = false;
			callar(g.fin);
		}
	}
}

// Panel de pruebas (DEPURAR = true).
function barra(v) {
	const n = Math.round(limitar(v, 0, 1) * 10);
	return '#'.repeat(n) + '.'.repeat(10 - n);
}

function pintarPanel(t) {
	if (!DEPURAR || typeof document === 'undefined' || !document.body) return;
	if (!panel) {
		panel = document.createElement('div');
		panel.style.cssText = 'position:fixed;top:8px;left:8px;z-index:50;padding:6px 8px;' +
			'background:rgba(0,0,0,.6);color:#fff;font:11px/1.4 monospace;border-radius:6px;' +
			'pointer-events:none;white-space:pre';
		document.body.appendChild(panel);
	}
	if (t - ultimoPanel < 100) return;
	ultimoPanel = t;
	const v = (g) => (face ? g.valor() : 0);
	const marca = (g) => (g.activo ? ' <<' : '');
	panel.textContent =
		'filtro   ' + (actual || 'ninguno') + '\n' +
		'parpadeo ' + barra(v(GESTOS.blink)) + ' ' + v(GESTOS.blink).toFixed(2) + marca(GESTOS.blink) + '\n' +
		'sonrisa  ' + barra(v(GESTOS.smileStart)) + ' ' + v(GESTOS.smileStart).toFixed(2) + marca(GESTOS.smileStart) + '\n' +
		'cejas    ' + barra(v(GESTOS.browRaise)) + ' ' + v(GESTOS.browRaise).toFixed(2) + marca(GESTOS.browRaise) + '\n' +
		(ultimoMensaje ? '> ' + ultimoMensaje : '');
}

// ---- API para los botones de la web ---------------------------------------

function setFilter(id) {
	if (id === '' || id === 'ninguno') id = null;
	if (id !== null && !FILTROS.some((f) => f.id === id)) {
		console.warn('Filtros: no existe el filtro "' + id + '"');
		return;
	}

	const f = FILTROS.find((x) => x.id === id);
	const t = performance.now();

	if (f && id === actual) {
		// Otro clic en el mismo boton.
		if (f.modo === 'partes') siguienteParte(f, t);
		else iniciarAnimacion(f, t);
	} else {
		callarTodos();
		actual = id;
		if (f) iniciarAnimacion(f, t);
	}

	sucio = true;
	if (listo) componer(t);
	window.dispatchEvent(new CustomEvent('filtro-cambiado', { detail: { id: actual } }));
}

if (player) {
	player.setFilter = setFilter;
	player.getFilter = () => actual;
	player.filterIds = FILTROS.map((f) => f.id);
}

// ---- Ciclo de vida --------------------------------------------------------

function start() {
	ocultarPlanos();
	iniciar();
}

function update(event) {
	const t = performance.now();
	procesarGestos();
	pintarPanel(t);

	if (!listo) {
		iniciar();
		return;
	}
	if (sucio || (animando && t - ultimoDibujo >= 1000 / FPS_ANIMACION)) componer(t);
}

// ---- Gestos de la cara ----------------------------------------------------
// Los gestos se miden en update() con GESTOS. Estas funciones solo sirven de
// respaldo si la pagina no entrega el objeto "face".

function blink(event)      { if (!face) sonar('blink'); }
function blinkEnd(event)   { if (!face) callar('blinkEnd'); }

function smileStart(event) { if (!face) sonar('smileStart'); }
function smileEnd(event)   { if (!face) callar('smileEnd'); }

function browRaise(event)  { if (!face) sonar('browRaise'); }
function browLower(event)  { if (!face) callar('browLower'); }

function faceLost(event)   { callarTodos(); }
